function E([string]$s){return [System.Net.WebUtility]::HtmlEncode($s)}
function Inline([string]$s,[string]$source){
  if(!$s){return ''}
  $s=[regex]::Replace($s,'!\[([^\]]*)\]\(([^)]+)\)',{param($m)'<span class="fad-image-note">'+(E $m.Groups[1].Value)+'</span>'})
  $s=[regex]::Replace($s,'\[([^\]]+)\]\(([^)]+)\)',{
    param($m)
    $label=$m.Groups[1].Value;$target=$m.Groups[2].Value
    if($target.StartsWith('http')){return '<a href="'+(E $target)+'" target="_blank" rel="noopener">'+(E $label)+'</a>'}
    $parts=$target -split '#',2;$path=$parts[0];$anchor=if($parts.Count -gt 1){'#'+$parts[1]}else{''}
    if(!$path){return '<a href="'+(E $anchor)+'">'+(E $label)+'</a>'}
    if($path -eq '../README.md' -or $path -eq 'README.md'){return '<a href="index.html">'+(E $label)+'</a>'}
    $base=[IO.Path]::GetDirectoryName($source).Replace('\','/');$combined=if($base){$base+'/'+$path}else{$path}
    $segments=New-Object Collections.Generic.List[string]
    foreach($seg in $combined.Split('/')){if($seg -eq '..'){if($segments.Count){$segments.RemoveAt($segments.Count-1)}}elseif($seg -and $seg -ne '.'){$segments.Add($seg)}}
    $norm=($segments -join '/')
    if($bySource.ContainsKey($norm)){return '<a href="'+$bySource[$norm].File+'">'+(E $label)+'</a>'}
    return '<span>'+ (E $label) +'</span>'
  })
  $s=[regex]::Replace($s,'`([^`]+)`','<code>$1</code>')
  $s=[regex]::Replace($s,'\*\*([^*]+)\*\*','<strong>$1</strong>')
  $s=[regex]::Replace($s,'(?<!\*)\*([^*]+)\*(?!\*)','<em>$1</em>')
  return $s
}
function Slug([string]$s,[int]$n){$v=[regex]::Replace($s,'[^\p{L}\p{Nd}]+','-').Trim('-').ToLower();if(!$v){$v='section-'+$n};return $v}
function Markdown([string]$md,[string]$source,[ref]$toc,[bool]$templates){
  $lines=$md -split "`r?`n";$out=New-Object Text.StringBuilder;$para=New-Object Collections.Generic.List[string];$state=@{List=''};$quote=New-Object Collections.Generic.List[string];$code=New-Object Collections.Generic.List[string];$inCode=$false;$table=New-Object Collections.Generic.List[string];$headCount=0;$codeCount=0
  function FlushPara(){if($para.Count){[void]$out.Append('<p>'+ (Inline (($para -join ' ') ) $source) +'</p>');$para.Clear()}}
  function FlushList(){if($state.List){[void]$out.Append('</'+$state.List+'>');$state.List=''}}
  function FlushQuote(){if($quote.Count){[void]$out.Append('<blockquote><p>'+ (Inline (($quote -join '<br>')) $source) +'</p></blockquote>');$quote.Clear()}}
  function FlushTable(){if($table.Count -ge 2){$rows=@();foreach($line in $table){$rows+=,@(($line.Trim('|') -split '\|')|ForEach-Object{$_.Trim()})};[void]$out.Append('<table><thead><tr>');foreach($c in $rows[0]){[void]$out.Append('<th>'+(Inline $c $source)+'</th>')};[void]$out.Append('</tr></thead><tbody>');for($ri=2;$ri -lt $rows.Count;$ri++){[void]$out.Append('<tr>');foreach($c in $rows[$ri]){[void]$out.Append('<td>'+(Inline $c $source)+'</td>')};[void]$out.Append('</tr>')};[void]$out.Append('</tbody></table>')};$table.Clear()}
  foreach($line in $lines){
    if($line -match '^```'){FlushPara;FlushList;FlushQuote;FlushTable;if($inCode){$codeCount++;$cid='tpl-'+$codeCount;$button=if($templates){'<button class="fad-copy" data-copy-target="'+$cid+'">复制模板</button>'}else{''};[void]$out.Append('<pre>'+$button+'<code id="'+$cid+'">'+(E ($code -join "`n"))+'</code></pre>');$code.Clear();$inCode=$false}else{$inCode=$true};continue}
    if($inCode){$code.Add($line);continue}
    if($line -match '^\s*\|.*\|\s*$'){FlushPara;FlushList;FlushQuote;$table.Add($line);continue}else{FlushTable}
    if([string]::IsNullOrWhiteSpace($line)){FlushPara;FlushList;FlushQuote;continue}
    if($line -match '^# '){continue}
    if($line -match '^(##|###)\s+(.+)$'){FlushPara;FlushList;FlushQuote;$level=$Matches[1].Length;$title=$Matches[2];$headCount++;$id=Slug $title $headCount;$toc.Value+=,@{Level=$level;Id=$id;Title=$title};[void]$out.Append('<h'+$level+' id="'+$id+'">'+(Inline $title $source)+'</h'+$level+'>');continue}
    if($line -match '^>\s?(.*)$'){$quote.Add($Matches[1]);continue}
    if($line -match '^---+$'){FlushPara;FlushList;FlushQuote;[void]$out.Append('<hr>');continue}
    if($line -match '^\s*[-*]\s+\[([ xX])\]\s+(.+)$'){FlushPara;if($state.List -ne 'ul'){FlushList;$state.List='ul';[void]$out.Append('<ul class="fad-checklist">')};$checked=if($Matches[1] -match '[xX]'){' checked'}else{''};[void]$out.Append('<li><label><input class="fad-check" type="checkbox"'+$checked+'>'+(Inline $Matches[2] $source)+'</label></li>');continue}
    if($line -match '^\s*[-*]\s+(.+)$'){FlushPara;if($state.List -ne 'ul'){FlushList;$state.List='ul';[void]$out.Append('<ul>')};[void]$out.Append('<li>'+(Inline $Matches[1] $source)+'</li>');continue}
    if($line -match '^\s*\d+[\.、]\s+(.+)$'){FlushPara;if($state.List -ne 'ol'){FlushList;$state.List='ol';[void]$out.Append('<ol>')};[void]$out.Append('<li>'+(Inline $Matches[1] $source)+'</li>');continue}
    $para.Add($line.Trim())
  }
  FlushPara;FlushList;FlushQuote;FlushTable
  return $out.ToString()
}

