  $map.decision='<text x="380" y="28" text-anchor="middle" fill="var(--fad-ink)" font-size="17" font-weight="700">工具选择决策树：先问题，后工具</text><rect x="280" y="55" width="200" height="55" rx="12" fill="var(--fad-surface)" stroke="var(--fad-amber)"/><text x="380" y="88" text-anchor="middle" fill="var(--fad-ink)" font-weight="700">它降低了真实摩擦吗？</text><path d="M330 110L190 175M430 110L570 175" stroke="var(--fad-amber)" stroke-width="3"/><rect x="80" y="175" width="220" height="70" rx="14" fill="rgba(181,92,76,.12)" stroke="var(--fad-danger)"/><rect x="460" y="175" width="220" height="70" rx="14" fill="rgba(54,129,107,.12)" stroke="var(--fad-good)"/><text x="190" y="205" text-anchor="middle" fill="var(--fad-danger)" font-weight="700">没有：不要增加新系统</text><text x="190" y="226" text-anchor="middle" fill="var(--fad-muted)" font-size="11">工具本身也会产生维护成本</text><text x="570" y="205" text-anchor="middle" fill="var(--fad-good)" font-weight="700">有：再看是否足够简单</text><text x="570" y="226" text-anchor="middle" fill="var(--fad-muted)" font-size="11">默认、可迁移、易导出</text><path d="M570 245V305" stroke="var(--fad-good)" stroke-width="3" marker-end="url(#a)"/><text x="570" y="330" text-anchor="middle" fill="var(--fad-good)">选择最小可用工具栈</text>'
  return $head+$map[$type]+$tail
}

function ChapterNav([string]$current,[bool]$mobile=$false){
  $p=$byId[$current];$ids=$groups[$p.Group].Ids;$s='<ul class="fad-chapter-nav">'
  foreach($id in $ids){$x=$byId[$id];$active=if($id -eq $current){' active'}else{''};$s+='<li><a class="'+$active.Trim()+'" href="'+$x.File+'"><span class="nav-state">'+$x.Index.ToString('00')+'</span><span>'+(E $x.Label)+'</span></a></li>'}
  return $s+'</ul>'
}

foreach($page in $pages){
  $sourcePath=Join-Path $SourceRoot $page.Source;$md=[IO.File]::ReadAllText($sourcePath)
  $title=[regex]::Match($md,'(?m)^#\s+(.+)$').Groups[1].Value.Trim();$problem=[regex]::Match($md,'(?m)^>\s*本篇解决：(.+)$').Groups[1].Value.Trim()
  $md=[regex]::Replace($md,'(?m)^#\s+.+\r?\n?','',1);$md=[regex]::Replace($md,'(?m)^>\s*本篇解决：.+\r?\n?','',1)
  $toc=@();$body=Markdown $md $page.Source ([ref]$toc) ($page.Id -eq 'templates')
  if($page.Group -eq 'cases'){$body=$body -replace '<li><label><input class="fad-check"','<li><label><input class="fad-check"'}
  $tocHtml=($toc|Where-Object{$_.Level -eq 2}|ForEach-Object{'<a data-toc href="#'+$_.Id+'">'+(E $_.Title)+'</a>'}) -join ''
  $prev=if($page.Index -gt 1){$pages[$page.Index-2]}else{$null};$next=if($page.Index -lt $pages.Count){$pages[$page.Index]}else{$null}
  if($prev){$prevHtml='<a href="'+$prev.File+'"><small>← 上一篇</small><strong>'+(E $prev.Label)+'</strong></a>'}else{$prevHtml='<a href="index.html"><small>← 返回</small><strong>专题首页</strong></a>'}
  if($next){$nextHtml='<a class="next" href="'+$next.File+'"><small>下一篇 →</small><strong>'+(E $next.Label)+'</strong></a>'}else{$nextHtml='<a class="next" href="index.html"><small>完成 →</small><strong>返回知识地图</strong></a>'}
  $pagination='<nav class="fad-pagination">'+$prevHtml+$nextHtml+'</nav>'
  $templateActions=if($page.Id -eq 'templates'){'<div class="fad-template-actions"><button class="fad-inline-btn" data-reset-checks>重置全部勾选</button></div>'}else{''}
  $html=@"
<!DOCTYPE html><html lang="zh-CN" data-theme="light"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"><meta name="description" content="$(E $problem)"><title>$(E $title) · 对抗无序</title><script>(function(){var t=localStorage.getItem('hk-theme')||'light';document.documentElement.setAttribute('data-theme',t)})();</script><link rel="stylesheet" href="assets/style.css"><link rel="stylesheet" href="../assets/storygarden.css"></head>
<body class="fad" data-sg-page data-sg-section="disorder" data-sg-title="$(E $title)" data-sg-root=".." data-sg-parent="index.html" data-sg-parent-label="返回对抗无序" data-fad-id="$($page.Id)">
<div hidden>$allNav</div><div class="fad-article-shell"><aside class="fad-rail"><a class="fad-rail-home" href="index.html">← 对抗无序</a><p class="fad-rail-title">$(E $page.GroupName)</p>$(ChapterNav $page.Id)</aside><main class="fad-article"><header class="fad-article-header"><span class="fad-kicker">Chapter $($page.Index.ToString('00')) · $(E $page.GroupName)</span><h1>$(E $title)</h1><p class="question">$(E $problem)</p><div class="fad-meta"><span>约 $($page.Minutes) 分钟</span><span>第 $($page.Index) / 23 篇</span><span>离线可读</span></div></header>
$(Diagram $page.Visual $title)
<details class="fad-mobile-tools"><summary>本章目录</summary>$(ChapterNav $page.Id)</details>
<article class="fad-body">$templateActions$body<div class="fad-micro"><b>现在就试一下：</b>$(E $page.Micro)</div></article>$pagination</main>
<aside class="fad-aside"><div class="fad-card fad-aside-card"><h3>本篇解决</h3><p>$(E $problem)</p></div><div class="fad-card fad-aside-card"><h3>本页目录</h3><nav class="fad-page-toc">$tocHtml</nav></div></aside></div>
<script src="../assets/search-index.js"></script><script src="../assets/storygarden.js"></script><script src="assets/app.js"></script></body></html>
"@
  [IO.File]::WriteAllText((Join-Path $OutRoot $page.File),$html,$utf8)
}

